mapper.data:
{
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "user",
      "content": "Write a 3-sentence re-engagement email to {{5.contact_name}} at {{5.business_name}}. They looked at AI automation 30+ days ago but did not move forward. Times change — check in warmly. Offer a no-pressure 15-min catch-up. Return only the email body, no subject line, no salutation, no sign-off."
    }
  ],
  "max_tokens": 300,
  "temperature": 0.75
}

{
  "from": "Brian at CWI AI <{{env.CWI_ALERT_FROM_ADDRESS}}>",
  "to": ["{{5.contact_email}}"],
  "subject": "Checking in — things may have changed",
  "text": "Hi {{5.contact_name}},

{{6.data.choices[0].message.content}}

If a quick 15-minute conversation sounds useful, you can grab a time here: {{env.CALENDLY_LINK}}

No pressure at all — just wanted to check in.

Brian
CWI AI"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ERROR] Scenario Q Cold Lead Re-engagement Failed",
  "html": "<h2 style='color:#dc2626;'>Scenario Q Error</h2><p>The Cold Lead Re-engagement scenario (Scenario Q) encountered an error and did not complete successfully for one or more deals.</p><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Error Message</td><td style='padding:6px 12px;'>{{error.message}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Failed Module</td><td style='padding:6px 12px;'>{{error.module}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Time</td><td style='padding:6px 12px;'>{{formatDate(now; 'MMMM D, YYYY h:mm A'; 'America/New_York')}} ET</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Deal Name</td><td style='padding:6px 12px;'>{{5.deal_name}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Deal ID</td><td style='padding:6px 12px;'>{{5.deal_id}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Contact Email</td><td style='padding:6px 12px;'>{{5.contact_email}}</td></tr></table><p>Please check the Make.com execution log and follow up with this contact manually if needed.</p>"
}
